def page(title,body,page='explore',desc='Find Utah holiday celebrations, light displays, live shows, markets, community events and seasonal experiences.',extra='',scripts_extra=''):
 return f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#19201d"><title>{E(title)} | Utah Seasonal Guide</title><meta name="description" content="{E(desc,quote=True)}">{styles}{extra}</head><body data-page="{page}" data-theme="winter"><a class="skip" href="#main">Skip to main content</a>{icons}{nav}{body}{footer}{scripts}{scripts_extra}</body></html>\n'
def options(items):return ''.join(f'<option value="{E(str(k),quote=True)}">{E(str(v))}</option>' for k,v in items)
index='''<section class="hero"><div class="hero-inner"><div><div class="eyebrow" id="heroEyebrow">Fall & winter 2026–27</div><h1 id="heroTitle">Your next good reason to get out.</h1><p id="heroDescription">Discover Utah’s seasonal celebrations, local traditions, shows and wonderfully unexpected things to do.</p><div class="hero-stats"><div class="stat"><b id="stat-events"></b><span>ideas to explore</span></div><div class="stat"><b id="stat-confirmed"></b><span>announced events</span></div><div class="stat"><b id="stat-regions"></b><span>Utah regions</span></div></div></div><div class="hero-art"><img id="heroArt" src="/assets/art/seasonal/winter-community.svg" width="1600" height="900" alt=""></div></div></section>
<main id="main" tabindex="-1"><div class="page-head"><div class="season-chip" id="seasonLabel">All celebrations · 2026–27</div><h2>Find your kind of celebration.</h2><p>Pick a holiday, then narrow it down by date, place and what you feel like doing.</p></div><nav id="seasonPicker" class="season-picker" aria-label="Choose a holiday"></nav><div class="quick-picks"><a href="/?when=weekend">This weekend</a><a href="/?when=tonight">Tonight</a><a href="/?free=1">Free admission</a><a href="/?community=LGBTQ%2B">Queer community</a><a href="/?category=Giving+%26+Volunteering">Give a little back</a></div><section class="controls compact-controls" aria-label="Event filters"><div class="search-row"><label class="sr-only" for="search">Search events, cities or activities</label><input id="search" class="search" type="search" placeholder="Search an event, city or activity"><button id="favoritesOnly" class="btn-filter" type="button" aria-pressed="false">☆ Saved events</button></div><div class="primary-filter-grid"><label class="filter-control"><span>When</span><select id="whenFilter">WHEN</select></label><label class="filter-control"><span>Where</span><select id="regionFilter"><option value="">All regions</option></select></label><label class="filter-control"><span>What</span><select id="categoryFilter"><option value="">All activities</option></select></label><details id="moreFilters" class="more-filters"><summary>More filters <span id="moreFilterCount" class="filter-count" hidden></span></summary><div class="more-filter-grid"><label class="filter-control"><span>Audience</span><select id="ageFilter"><option value="">Any audience</option></select></label><label class="filter-control"><span>Price</span><select id="costFilter">COST</select></label><label class="filter-control"><span>Scare level</span><select id="scareFilter">SCARE</select></label><label class="filter-control"><span>Good to know</span><select id="flagFilter"><option value="">Any practical details</option></select></label><label class="filter-control"><span>Community / tradition</span><select id="communityFilter"><option value="">Any community</option></select></label><label class="check-filter"><input id="freeOnly" type="checkbox">Free admission only</label><label class="check-filter"><input id="includeWatch" type="checkbox">Include announcements pending</label><label class="filter-control"><span>Sort</span><select id="sortFilter"><option value="date">Next available date</option><option value="name">A–Z</option><option value="cost">Lowest cost first</option></select></label></div></details></div><div id="customDateWrap" class="custom-date-wrap" hidden><label class="filter-control"><span>Choose a date</span><input type="date" id="datePick" min="2026-09-01" max="2027-03-31"></label></div><div class="active-filter-row"><div id="activeFilters" role="group" class="active-filters" aria-label="Active filters"></div><button id="clearFilters" class="clear-all" type="button" hidden>Clear all</button></div><p class="search-hint">Tonight and Open now use confirmed evening hours, in Utah time. Free admission may still have optional purchases or parking costs.</p></section><div class="resultsbar" role="status" aria-live="polite"><div><strong id="resultCount"></strong> matches</div><div id="filterSummary"></div></div><section id="eventCards" class="cards" aria-label="Events"></section><button id="loadMore" class="loadmore" type="button">Show more events</button><noscript><p>Use an event’s page to plan your visit. Interactive search needs JavaScript.</p><ul>NOJS</ul></noscript></main>'''
index=index.replace('WHEN',options([('','Any date'),('today','Today'),('tonight','Tonight'),('open-now','Open now'),('tomorrow','Tomorrow'),('weekend','This weekend'),('next-weekend','Next weekend'),('date','Pick a date…')])).replace('COST',options([('','Any price'),(1,'Free / very low'),(2,'Up to $25'),(3,'$26–50'),(4,'$51–100'),(5,'Over $100'),(0,'Price not announced')])).replace('SCARE',options([('','Any scare level'),(1,'1 · Gentle'),(2,'2 · Light'),(3,'3 · Moderate'),(4,'4 · Scary'),(5,'5 · Extreme')])).replace('NOJS',''.join(f'<li><a href="/events/{e["id"]}/">{E(e["Event / attraction"])}</a></li>' for e in d['events'] if not e['isWatch']))
pathlib.Path('index.html').write_text(page('Utah holiday events & seasonal adventures',index,extra=f'<link rel="canonical" href="{base}/">'))
# Short public copy focuses on visitors, not research procedures.
about='''<main id="main" tabindex="-1"><div class="page-head"><h1>More ways to celebrate Utah.</h1><p>For locals, visitors, families, friends and anyone looking for a good reason to get out.</p></div><div class="detail-layout"><section class="info-card prose"><h2>Find a celebration that fits</h2><p>Explore Halloween and fall, Thanksgiving, Christmas, Hanukkah, Diwali, Kwanzaa, Yule and solstice, Veterans Day, New Year and winter experiences. Some events belong to more than one tradition; choose whichever speaks to you.</p><h2>What the ratings mean</h2><p>Scare level describes intensity, from gentle (1) to extreme (5). Festive Factor describes the amount of seasonal atmosphere, from a light touch (1) to an immersive celebration (5). Activity level runs from relaxed (1) to demanding (5). These are editorial guides to the advertised experience, not customer reviews or judgments about a tradition.</p><h2>Access and accommodations</h2><p>Find organizer information about wheelchair access, adaptive appointments and other accommodations on event pages when it is available. An event without access information may still offer the support you need. Ask the organizer about your requirements before booking.</p><p>If something on this website prevents you from using it, <a href="mailto:jerekeys@gmail.com?subject=Utah%20Seasonal%20Guide%20accessibility">email Jere</a> with the page and what happened.</p></section><aside class="info-card prose"><h2>Before you go</h2><p>Check the event page for tickets, weather closures, cancellations and the latest hours. Prices can vary by date and may have fees.</p><h2>Your saved events</h2><p>Save ideas as you browse. Your list stays in this browser, so you can use it without an account.</p><h2>Help make the guide better</h2><p><a href="/submit/">Suggest an event, report a correction or share access information</a>. Contact information submitted privately will not be published.</p><h2>Images</h2><p>Event photos have source credits. Illustrated cards are holiday artwork, rather than photographs of the venue.</p></aside></div></main>'''
pathlib.Path('about.html').write_text(page('About the guide',about,'about'))
for name,pg,title,desc,host in [('weekend','weekend','Your weekend, your way.','Find events happening this Friday through Sunday.','planner'),('itineraries','routes','Make a day of it.','Pair an experience with food, a stroll or something unexpected nearby.','routes'),('vibes','vibes','What sounds good today?','Start with a mood, then find a celebration that fits.','vibesGrid'),('standouts','standouts','A few good places to start.','A mix of immersive spectacles, local traditions and thoughtful experiences.','standoutsGrid')]:
 body=f'<main id="main" tabindex="-1"><div class="page-head"><h1>{title}</h1><p>{desc}</p></div><div class="quick-picks"><a href="/?when=weekend">Browse this weekend</a><a href="/?free=1">Free admission</a><a href="/?saved=1">Your saved events</a></div><section id="{host}" class="vibe-grid"></section></main>'
 pathlib.Path(name+'.html').write_text(page(title,body,pg))
pathlib.Path('image-credits.html').write_text(page('Image credits','<main id="main" tabindex="-1"><div class="page-head"><h1>Image credits</h1><p>Photos from the events and places featured in this guide. Illustrated cards use original seasonal icon artwork.</p></div><div id="imageCredits" class="vibe-grid"></div></main>','credits'))
# Form is handled as an explicit email composition during preview, avoiding a pretend delivered success.
form='''<main id="main" tabindex="-1"><div class="page-head"><h1>Share a good find.</h1><p>Suggest an event, correct a detail or tell us about an accommodation.</p></div><div class="notice">Your email is only for follow-up. During preview testing, the form opens an email to Jere for you to review and send.</div><form class="submission-form" id="submissionForm"><div class="field"><label for="submission-kind">What would you like to share?</label><select id="submission-kind" name="kind"><option>Suggest an event</option><option>Correct a listing</option><option>Share accessibility information</option><option>Report a website issue</option></select></div><div class="field"><label for="event-name">Event name (required)</label><input id="event-name" name="event-name" required maxlength="180"></div><div class="field"><label for="official-url">Event page (required)</label><input id="official-url" name="official-url" type="url" required placeholder="https://…"></div><div class="field"><label for="holidays">Holiday(s) / season</label><input id="holidays" name="holidays" placeholder="Christmas, Hanukkah, winter…"></div><div class="field"><label for="location">Venue and city</label><input id="location" name="location" maxlength="250"></div><div class="date-fields"><div class="field"><label for="start-date">First date</label><input id="start-date" name="start-date" type="date"></div><div class="field"><label for="end-date">Last date</label><input id="end-date" name="end-date" type="date"></div></div><div class="field"><label for="schedule">Hours and specific dates</label><textarea id="schedule" name="schedule" placeholder="List opening hours, performance times and any closed dates." maxlength="700"></textarea></div><div class="field"><label for="price">Admission and age requirements</label><input id="price" name="price" maxlength="250"></div><div class="field"><label for="description">Details or correction (required)</label><textarea id="description" name="description" required maxlength="2000"></textarea></div><fieldset class="fieldset"><legend>Access and accommodations</legend><div class="field"><label for="access-details">What should visitors know?</label><textarea id="access-details" name="access-details" maxlength="700" placeholder="Mobility, vision, hearing, sensory accommodations or limitations."></textarea></div><div class="field"><label for="access-url">Organizer’s access information</label><input id="access-url" name="access-url" type="url"></div></fieldset><fieldset class="fieldset"><legend>Photo or promotional image</legend><div class="field"><label for="image-url">Image or media-kit link</label><input id="image-url" name="image-url" type="url"></div><div class="field"><label for="image-credit">Photographer and required credit</label><input id="image-credit" name="image-credit" maxlength="250"></div><label><input id="image-permission" name="image-permission" type="checkbox" value="yes"> I own this image or have permission to share it for use in the guide.</label></fieldset><fieldset class="fieldset"><legend>About you</legend><div class="field"><label for="submitter-name">Name</label><input id="submitter-name" name="submitter-name" autocomplete="name"></div><div class="field"><label for="submitter-email">Email</label><input id="submitter-email" name="submitter-email" type="email" autocomplete="email"></div></fieldset><button class="button primary" type="submit">Review & send by email</button><div id="formFeedback" class="form-feedback" role="status" hidden></div></form><p>Prefer a direct email? <a href="mailto:jerekeys@gmail.com?subject=Utah%20Seasonal%20Guide%20submission">Send it to jerekeys@gmail.com</a>.</p></main>'''
pathlib.Path('submit.html').write_text(page('Suggest an event or correction',form,'submit',scripts_extra='<script src="/assets/submission.js"></script>'))
pathlib.Path('thanks.html').write_text(page('Thanks for helping','<main id="main" tabindex="-1"><h1>Thanks for helping the guide grow.</h1><p>If you used the preview form, complete the send in your email app.</p><a class="button primary" href="/">Back to exploring</a></main>','thanks'))
# Real files for human-friendly URLs, with HTML compatibility redirects.
paths=['about','weekend','itineraries','vibes','standouts','submit','thanks','image-credits'];redirects=[]
for name in paths:
 out=pathlib.Path(name);out.mkdir(exist_ok=True);s=pathlib.Path(name+'.html').read_text().replace('</head>',f'<link rel="canonical" href="{base}/{name}/"></head>');(out/'index.html').write_text(s);redirects.append(f'/{name}.html /{name}/ 301')
pathlib.Path('event.html').write_text(page('Event details','<main id="main" tabindex="-1"><section id="eventDetail"></section></main>','event',scripts_extra='<script>const id=new URLSearchParams(location.search).get("id");if(id&&window.SITE_DATA.events.some(e=>e.id===id))location.replace("/events/"+encodeURIComponent(id)+"/");</script>'))
out=pathlib.Path('events');shutil.rmtree(out,ignore_errors=True);out.mkdir()
urls=[base+'/']+[base+'/'+n+'/' for n in paths if n!='thanks']
for e in d['events']:
 slug=e['id'];o=out/slug;o.mkdir();title=e['Event / attraction'];desc=e['Why / thoughts'][:155];canonical=base+'/events/'+slug+'/'
 fallback=f'<h1>{E(title)}</h1><p>{E(e["2026 schedule"])}</p><p>{E(e["Location"])}</p><p>{E(e["Price"])}</p><p>{E(e["Why / thoughts"])}</p><a href="{E(e["Website"],quote=True)}">Organizer’s event page</a>'
 extra=f'<link rel="canonical" href="{canonical}"><meta property="og:title" content="{E(title,quote=True)}"><meta property="og:description" content="{E(desc,quote=True)}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{base}/assets/share/{e.get("theme","winter")}.png">'
 if not e['isWatch'] and e.get('occurrenceDates'):
  ld={'@context':'https://schema.org','@type':'Event','name':title,'description':e['Why / thoughts'],'url':canonical,'startDate':e['occurrenceDates'][0],'eventStatus':'https://schema.org/EventScheduled','location':{'@type':'Place','name':e['Location']}};extra+='<script type="application/ld+json">'+json.dumps(ld,ensure_ascii=False).replace('</','<\/')+'</script>'
 body=f'<main id="main" tabindex="-1"><section id="eventDetail">{fallback}</section></main>'
 text=page(title,body,'event',desc,extra=extra).replace('<script src="/assets/data.js">',f'<script>window.EVENT_ID={json.dumps(slug)};</script><script src="/assets/data.js">');(o/'index.html').write_text(text)
 if not e['isWatch']:urls.append(canonical)
pathlib.Path('_redirects').write_text('\n'.join(redirects)+'\n')
pathlib.Path('sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join(f'<url><loc>{E(u)}</loc></url>\n' for u in urls)+'</urlset>\n')
pathlib.Path('robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+base+'/sitemap.xml\n')
print('Generated',len(d['events']),'event pages and',len(urls),'sitemap entries')
